	RockNode.cpu_clock = true
	var use_async := OS.get_cmdline_user_args().has("async=1")
	var worst_all := 0
	var digs := []
	var cases := [["pine", 0.3, 18.0, 0.35, 11], ["pine", 0.55, 26.0, 0.3, 12], ["oak", 0.45, 16.0, 0.4, 13], ["birch", 0.25, 14.0, 0.35, 14],
