		var arr := PineMesh.arrays_of(cp.mesh)
		var t_mesh := RockNode._now() - t0
		t0 = RockNode._now()
		var d: Dictionary
		var slices := 0
		var worst := 0
		if use_async:
			var h := Branches.template_async(c[0], c[1], c[2], c[3], c[4])
			var last := RockNode._now()
			while not Branches.template_cached(c[0], c[1], c[2], c[3], c[4]):
				worst = maxi(worst, RockNode._now() - last)
				await process_frame
				last = RockNode._now()
				slices += 1
			worst = maxi(worst, RockNode._now() - last)
			d = Branches.template(c[0], c[1], c[2], c[3], c[4])
