		var t_all := RockNode._now() - t0
		var dg := hash(str(d.wood) + str(d.fol) + str(d.branches.size()))
		for b: Dictionary in d.branches:
			dg = hash([dg, (b.rod.xf as Transform3D).origin, b.rod.len, b.rod.r0, b.fol, b.live, (b.fv as PackedVector3Array).size()])
		digs.append(dg)
		worst_all = maxi(worst_all, worst)
		print("TMPL %s d=%.2f h=%.0f: crown mesh %d us, template %d us (%s), branches %d, digest %d slices %d worst slice %d us" % [c[0], c[1], c[2], t_mesh, t_all,
			"async" if use_async else "sync", d.branches.size(), dg, slices, worst])
